import openpyxl, re
path='/root/copy_of_capacity_sheet.xlsx'
wb=openpyxl.load_workbook(path, data_only=True)
print('sheets:', wb.sheetnames)
ws=wb['Weld']
# find row containing MIG weld Demand Total
label_re=re.compile(r"MIG\s*weld\s*Demand\s*Total", re.I)
label_row=None
label_cell=None
for row in ws.iter_rows(values_only=False):
    for cell in row:
        v=cell.value
        if isinstance(v,str) and label_re.search(v):
            label_row=cell.row
            label_cell=cell
            break
    if label_row:
        break
print('label_row:', label_row, 'label_cell:', label_cell.coordinate if label_cell else None, 'label_value:', label_cell.value if label_cell else None)
# find header row mapping weeks
# assume header row is above label row; scan rows 1..label_row for numeric weeks 1..52
week_to_col={}
header_row=None
for r in range(1, (label_row or 1)):
    for c in range(1, ws.max_column+1):
        v=ws.cell(r,c).value
        if isinstance(v,(int,float)) and int(v)==v and 1<=int(v)<=60:
            # treat as week number
            wk=int(v)
            # pick the first row where we see multiple week numbers
            week_to_col.setdefault(wk,[]).append((r,c))
# choose the row that covers 4..52 most
row_scores={}
for wk,locs in week_to_col.items():
    for r,c in locs:
        row_scores.setdefault(r,set()).add(wk)
if row_scores:
    best=max(row_scores.items(), key=lambda kv: (len([w for w in kv[1] if 4<=w<=52]), len(kv[1])))
    header_row=best[0]
    weeks=best[1]
    print('best header_row:', header_row, 'weeks_found_count:', len(weeks))
else:
    print('no numeric weeks in rows')

# Build mapping for that header row: week->col for weeks 1..60
if header_row:
    mapping={}
    for c in range(1, ws.max_column+1):
        v=ws.cell(header_row,c).value
        if isinstance(v,(int,float)) and int(v)==v:
            wk=int(v)
            if 1<=wk<=60 and wk not in mapping:
                mapping[wk]=c
    missing=[wk for wk in range(4,53) if wk not in mapping]
    print('weeks 4-52 missing:', missing[:10], '... total missing', len(missing))
    # extract values
    demand={}
    for wk in range(4,53):
        c=mapping.get(wk)
        v=ws.cell(label_row,c).value if c else None
        if v is None:
            v=0
        demand[wk]=float(v) if isinstance(v,(int,float)) else 0.0
    # print first few / last few
    first=[(wk,demand[wk]) for wk in range(4,10)]
    last=[(wk,demand[wk]) for wk in range(47,53)]
    print('first few:', first)
    print('last few:', last)

wb.close()
