print('sheets:', wb.sheetnames)
ws=wb['Weld']
label_re=re.compile(r"MIG\s*weld\s*Demand\s*Total", re.I)
label_row=None
label_cell=None
for row in ws.iter_rows(values_only=False):
    for cell in row:
        v=cell.value
        if isinstance(v,str) and label_re.search(v):
            label_row=cell.row
            label_cell=cell
            break
    if label_row:
        break
print('label_row:', label_row, 'label_cell:', label_cell.coordinate if label_cell else None)
print('label_value:', repr(label_cell.value) if label_cell else None)

# find header row with week numbers 4..52
row_weekset={}
for r in range(1, (label_row or 1)):
    s=set()
    for c in range(1, ws.max_column+1):
        v=ws.cell(r,c).value
        if isinstance(v,(int,float)) and int(v)==v and 1<=int(v)<=60:
            s.add(int(v))
    if s:
        row_weekset[r]=s
if not row_weekset:
    raise SystemExit('Could not find any row with numeric week headers')
header_row=max(row_weekset.items(), key=lambda kv: (sum(1 for w in kv[1] if 4<=w<=52), len(kv[1])))[0]
print('chosen header_row:', header_row, 'weeks_in_row:', sorted(list(row_weekset[header_row]))[:15], '...')

mapping={}
for c in range(1, ws.max_column+1):
    v=ws.cell(header_row,c).value
    if isinstance(v,(int,float)) and int(v)==v:
        wk=int(v)
        if 1<=wk<=60 and wk not in mapping:
            mapping[wk]=c
missing=[wk for wk in range(4,53) if wk not in mapping]
print('missing weeks 4-52:', missing)

demand={}
for wk in range(4,53):
    c=mapping[wk]
    v=ws.cell(label_row,c).value
    if v is None:
        v=0
    demand[wk]=float(v) if isinstance(v,(int,float)) else 0.0

first=[(wk, demand[wk]) for wk in range(4,10)]
last=[(wk, demand[wk]) for wk in range(47,53)]
print('first few:', first)
print('last few:', last)

wb.close()
